    operator fun not() = BVec3(!x, !y, !z)
    fun toVec3() = Vec3(if (x) 1f else 0f, if (y) 1f else 0f, if (z) 1f else 0f)
    fun toDVec3() = DVec3(if (x) 1.0 else 0.0, if (y) 1.0 else 0.0, if (z) 1.0 else 0.0)
    fun toIVec3() = IVec3(if (x) 1 else 0, if (y) 1 else 0, if (z) 1 else 0)
    fun toUVec3() = UVec3(if (x) 1u else 0u, if (y) 1u else 0u, if (z) 1u else 0u)
    override fun toString() = "($x, $y, $z)"
}

/** kor::BVec4: 4 Booleans, immutable. */
data class BVec4(val x: Boolean, val y: Boolean, val z: Boolean, val w: Boolean) {
    constructor(s: Boolean) : this(s, s, s, s)
    constructor(xyz: BVec3, w: Boolean) : this(xyz.x, xyz.y, xyz.z, w)
    constructor(x: Boolean, yzw: BVec3) : this(x, yzw.x, yzw.y, yzw.z)
    constructor(xy: BVec2, z: Boolean, w: Boolean) : this(xy.x, xy.y, z, w)
    constructor(x: Boolean, yz: BVec2, w: Boolean) : this(x, yz.x, yz.y, w)
    constructor(x: Boolean, y: Boolean, zw: BVec2) : this(x, y, zw.x, zw.y)
    constructor(xy: BVec2, zw: BVec2) : this(xy.x, xy.y, zw.x, zw.y)

    operator fun get(i: Int): Boolean = when (i) { 0 -> x; 1 -> y; 2 -> z; 3 -> w; else -> throw IndexOutOfBoundsException(i) }
    /** The same with component i replaced: `v.with(1, 0f)`. */
    fun with(i: Int, value: Boolean) = when (i) { 0 -> copy(x = value); 1 -> copy(y = value); 2 -> copy(z = value); 3 -> copy(w = value); else -> throw IndexOutOfBoundsException(i) }
    fun toArray() = booleanArrayOf(x, y, z, w)
    infix fun and(o: BVec4) = BVec4(x and o.x, y and o.y, z and o.z, w and o.w)
    infix fun or(o: BVec4) = BVec4(x or o.x, y or o.y, z or o.z, w or o.w)
    infix fun xor(o: BVec4) = BVec4(x xor o.x, y xor o.y, z xor o.z, w xor o.w)
    operator fun not() = BVec4(!x, !y, !z, !w)
    fun toVec4() = Vec4(if (x) 1f else 0f, if (y) 1f else 0f, if (z) 1f else 0f, if (w) 1f else 0f)
    fun toDVec4() = DVec4(if (x) 1.0 else 0.0, if (y) 1.0 else 0.0, if (z) 1.0 else 0.0, if (w) 1.0 else 0.0)
    fun toIVec4() = IVec4(if (x) 1 else 0, if (y) 1 else 0, if (z) 1 else 0, if (w) 1 else 0)
    fun toUVec4() = UVec4(if (x) 1u else 0u, if (y) 1u else 0u, if (z) 1u else 0u, if (w) 1u else 0u)
    override fun toString() = "($x, $y, $z, $w)"
}
